from pathlib import Path

# DFDC
dfdc_base = Path('data/raw/cross_eval/dfdc')
for split in ['train', 'validation']:
    for label in ['real', 'fake']:
        folder = dfdc_base / split / label
        count = len(list(folder.glob('*.jpg')) + list(folder.glob('*.png')))
        print(f"DFDC/{split}/{label}: {count} images")

print()

# Faceswap
fs_base = Path('data/raw/cross_eval/faceswap/Dataset')
for split in ['Train', 'Test', 'Validation']:
    folder = fs_base / split
    if folder.exists():
        for subfolder in sorted(folder.iterdir()):
            if subfolder.is_dir():
                count = len(list(subfolder.glob('*.jpg')) + list(subfolder.glob('*.png')))
                print(f"Faceswap/{split}/{subfolder.name}: {count} images")
